def gqa_kv_cache_gb(num_layers: int, num_kv_heads: int, head_dim: int, seq_len: int, bytes_per_value: int) -> float:
    """KV cache size in GB under GQA: only num_kv_heads is stored, not num_query_heads."""
    total_bytes = 2 * num_layers * num_kv_heads * head_dim * seq_len * bytes_per_value
    return round(total_bytes / 1e9, 2)

print(gqa_kv_cache_gb(32, 8, 128, 4096, 2))
